arguments.code:
async function run() {
  const results = {};
  for (const dir of ["~/.agnes/recipes", "~/.agnes/rules"]) {
    try {
      const r = await Shell.run({ command: `ls -1 "${dir}" 2>/dev/null | wc -l && echo "---" && ls -1 "${dir}" 2>/dev/null` });
      results[dir] = r.stdout;
    } catch (e) {
      results[dir] = `ERROR: ${e.message || e}`;
    }
  }
  return results;
}

